import { test, expect } from '../../../fixtures/qa-test';
import { PATHS } from '../../../scripts/lib/paths';
import { readJsonIfExists, writeJson } from '../../../scripts/discovery/write-json';
import type { PlannedCheck } from '../../../scripts/planning/types';

// Data-driven: loops over planned-checks.json. Generated by the UI engine / qa:test.
function loadPlannedChecks(): PlannedCheck[] {
  try {
    return readJsonIfExists<PlannedCheck[]>(PATHS.plannedChecksFile) ?? [];
  } catch {
    return [];
  }
}

const checks = loadPlannedChecks();
const planned = checks.filter((check) => check.status === 'PLANNED');
const gated = checks.filter((check) => check.status !== 'PLANNED');

test('record gated planned checks as explicit outcomes (not Playwright skip)', { tag: ['@generated'] }, async () => {
  writeJson(PATHS.gatedCheckOutcomesFile, {
    generatedAt: new Date().toISOString(),
    policy: 'exhaustive-execution',
    note:
      'BLOCKED / NOT_TESTED / REQUIRES_CONFIGURATION rows are recorded here. They are not test.skip entries.',
    total: checks.length,
    planned: planned.length,
    gated: gated.length,
    rows: gated.map((check) => ({
      id: check.id,
      kind: check.kind,
      title: check.title,
      status: check.status,
      reason: check.reason ?? `${check.status}: no reason recorded`,
      targetUrl: check.targetUrl,
    })),
  });

  if (checks.length === 0) {
    expect(
      checks,
      'REQUIRES_CONFIGURATION: no discovery checks planned — run discovery/inventory first. This is not a silent skip of UI execution.'
    ).toEqual([]);
    return;
  }

  expect(gated.every((check) => Boolean(check.reason)), 'Every gated check must record a reason').toBe(true);
});

for (const check of planned) {
  test(`[${check.kind}] ${check.id} ${check.title}`, { tag: ['@generated'] }, async ({ discoveredPage }) => {
    const selector = check.expect?.locator;
    const control = check.expect?.control;

    switch (check.kind) {
      case 'page-sanity': {
        await discoveredPage.open(check.targetUrl);
        if (check.expect?.requireH1) await discoveredPage.expectHeadingVisible();
        else if (check.expect?.requireHeading) await discoveredPage.expectAnyHeadingVisible();
        else await discoveredPage.expectPageReady();
        break;
      }

      case 'broken-link': {
        if (check.expect?.href && selector) {
          await discoveredPage.open(check.targetUrl);
          const status = await discoveredPage.destinationStatus(check.expect.href, check.targetUrl);
          expect(status, `${check.expect.href} returned ${status}`).toBeGreaterThanOrEqual(200);
          expect(status, `${check.expect.href} returned ${status}`).toBeLessThan(400);
          break;
        }
        const status = await discoveredPage.openAllowingError(check.targetUrl);
        expect(status, `${check.targetUrl} returned ${status}`).toBeGreaterThanOrEqual(200);
        expect(status, `${check.targetUrl} returned ${status}`).toBeLessThan(400);
        break;
      }

      case 'visibility':
      case 'form-presence': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.expectVisible(selector);
        break;
      }

      case 'enabled-state': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.expectEnabledState(selector, check.expect?.enabled ?? true);
        break;
      }

      case 'editability': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.expectEditable(selector, check.expect?.readOnly);
        break;
      }

      case 'required-state': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.expectRequired(selector, Boolean(check.expect?.required));
        await discoveredPage.expectVisible(selector);
        break;
      }

      case 'required-validation':
      case 'empty-input':
      case 'form-boundary': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        if (check.expect?.required) await discoveredPage.expectRequired(selector, true);
        if (control === 'text' || !control) {
          await discoveredPage.fillWithoutSubmit(selector, check.expect?.fillValue ?? '');
          await discoveredPage.expectConstraintValidity(selector, !check.expect?.required);
        }
        await discoveredPage.expectVisible(selector);
        break;
      }

      case 'accessible-name': {
        if (!selector || check.expect?.accessibleName == null) throw new Error(`${check.id} missing accessible name`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.expectAccessibleName(selector, check.expect.accessibleName);
        break;
      }

      case 'valid-input':
      case 'whitespace-input':
      case 'long-input':
      case 'unicode-input':
      case 'special-characters':
      case 'boundary-values': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.fillWithoutSubmit(selector, check.expect?.fillValue ?? 'Sample text');
        await discoveredPage.expectVisible(selector);
        break;
      }

      case 'invalid-input':
      case 'validation-state': {
        if (!selector || check.expect?.fillValue == null) throw new Error(`${check.id} missing fill value`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.fillWithoutSubmit(selector, check.expect.fillValue);
        if (check.expect.constraintInvalid) {
          await discoveredPage.expectConstraintValidity(selector, false);
        } else {
          await discoveredPage.expectVisible(selector);
        }
        break;
      }

      case 'error-recovery': {
        if (!selector || check.expect?.fillValue == null || check.expect.recoveryValue == null) {
          throw new Error(`${check.id} missing recovery values`);
        }
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.recoverFromInvalid(selector, check.expect.fillValue, check.expect.recoveryValue);
        break;
      }

      case 'link-href': {
        if (!selector || !check.expect?.href) throw new Error(`${check.id} missing href`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.expectHref(selector, check.expect.href);
        break;
      }

      case 'click-link': {
        if (!selector || !check.expect?.href) throw new Error(`${check.id} missing href`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.clickLink(selector, check.expect.href, check.targetUrl);
        break;
      }

      case 'click-button': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.clickButton(selector);
        break;
      }

      case 'select-options':
      case 'select-change': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        await discoveredPage.selectFirstAlternative(selector);
        break;
      }

      case 'toggle-state': {
        if (!selector) throw new Error(`${check.id} missing locator`);
        await discoveredPage.open(check.targetUrl);
        if (control === 'radio') await discoveredPage.selectRadio(selector);
        else await discoveredPage.toggleCheckbox(selector);
        break;
      }

      case 'form-submit':
        throw new Error(
          `${check.id} was marked PLANNED as form-submit — the planner must record NOT_TESTED instead. Safety policy forbids generated submits.`
        );

      default:
        throw new Error(
          `${check.id} unhandled check kind ${String(check.kind)} was marked PLANNED. Record NOT_TESTED in the planner instead of skipping at runtime.`
        );
    }
  });
}
